INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('e1a20c1a-a01c-4186-9b7c-ed9350c5c5e1', '21feff02-016d-46e2-bb9d-c27495133b1b', '11. óra: Összeszámlálási feladatok megoldása', 'Önálló feladatmegoldás rendszerezett felsorolással és faábrával.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "d78d5e70-b6a8-425d-bb0a-23a6ec9ff537", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "c68b9584-3903-40f2-9853-da80c0067211", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "d8ff9c50-9748-4112-9475-1a388726ec6a", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "ccba1725-fccf-4628-afb2-041b1ee054f1", "text": "Igaz", "isCorrect": true}, {"id": "8a227d04-fa13-407f-8e7a-917345dca0a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "168b9ea3-340a-48cc-b228-eaf95287b0d5", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "68779e9e-0e7b-4d1a-845c-aa7aafc2769e", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "40c94dc6-daf0-4fe8-9710-36f24828aded", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "959ae025-f7c9-4d98-8a8b-6e09a8100e48", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "797e912d-ab0a-4ac6-8a9e-1f3de51fe75c", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "25deb348-df64-41ff-9c2a-424fd7390840", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "35438755-7016-4a22-8a28-3fb17dc93450", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "3124ad76-52a7-4e65-a9e0-e5e967a4ed6c", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "efdc01dc-8fe4-45c5-af72-6bcc4eaa7c76", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8384feb3-3860-4677-acf8-130c7697f1f8", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('091ccd8e-a61d-4cc9-851a-9034038f2fba', '21feff02-016d-46e2-bb9d-c27495133b1b', '12. óra: Számonkérés', 'Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "3882a20b-ce4d-4209-b3fc-df074aca3fd7", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "be82069b-ded5-4ee2-95ee-abf5549f5086", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "98314429-381d-4eee-aa39-a65879ab712c", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "28f97ce9-6901-4ad8-9515-ab17cd96f7e5", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "dffd4df9-112c-412c-b1df-bd0683251929", "text": "|-30|", "isCorrect": true}, {"id": "b0ca631b-42c4-4ce5-a027-3bb48422258f", "text": "|+20|", "isCorrect": false}, {"id": "25cd5eb1-f3ff-448d-a49c-8844ec601c11", "text": "Egyenlőek", "isCorrect": false}, {"id": "d46a9eab-4736-4436-8912-017cc4fa14ef", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "b2012ba1-368f-4aea-b31c-8e9a75d6148a", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "2faa48ca-2180-44f9-91e5-adfdad97c765", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "0f541192-6127-4c31-a028-54d6f9347b69", "text": "Igaz", "isCorrect": true}, {"id": "1e7c6575-2330-4b5e-9139-425faaef181e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "77564164-d658-48e1-b665-f9dc616394c5", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6c40721b-d6e1-4e5c-9fbb-2c5093e071ce", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "0af97164-defe-4d2b-8214-3c66dba256ae", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "a34c374e-e4da-4654-9ee2-2d69fd726b35", "text": "Igaz", "isCorrect": true}, {"id": "fcab9ac6-0bb1-483c-85a2-1e622857feec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "867be3a9-e7ed-4580-846a-0616b2c2c7de", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()),
('3b1e3ff5-bf04-405f-ab10-56cdd395781d', '21feff02-016d-46e2-bb9d-c27495133b1b', '13. óra: Osztó, többszörös', 'Osztó, többszörös fogalma, osztópárok meghatározása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "fdc43101-6e3b-4c60-878b-3600b38cb774", "text": "Mit nevezünk egy ''a'' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "aa66fcef-abbc-476a-84a4-07aae822fcca", "text": "Azt a ''b'' számot, amellyel ''a''-t elosztva a maradék 0", "isCorrect": true}, {"id": "d0890096-ff15-434e-bafe-46a3a109aebe", "text": "Azt a számot, amit ''a''-hoz hozzáadunk", "isCorrect": false}, {"id": "ab6402e2-ec5e-4d2a-9657-3a78153bb662", "text": "Azt a számot, ami nagyobb ''a''-nál", "isCorrect": false}, {"id": "fb434652-f71a-41d3-84d0-8f2e59bbde52", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "34250bd6-526a-4b90-acd6-3c4f06ac15b8", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "9eb67577-c049-4a06-9dfc-7ff4b7a1be33", "text": "Igaz", "isCorrect": true}, {"id": "6177199a-0ee0-48aa-8e63-2401f88ee9de", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "80e7a369-5047-4547-aa52-ceec212af88f", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "a400e021-00fb-43a8-8fbb-1ad4c0af12d6", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "bacc85a8-4bc9-48e9-bdfa-7a2b5eec5197", "text": "45", "isCorrect": true}, {"id": "621419b9-7ca1-4456-83bd-246353a365a5", "text": "5", "isCorrect": false}, {"id": "a1afa967-d510-4ce1-9d75-c2f8dcb709f6", "text": "3", "isCorrect": false}, {"id": "3faaae5d-632a-4454-b524-02993c1ddebc", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "21c7c73e-1aa5-47f4-a4aa-e0b0773a5a2e", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id": "421aba0f-23f8-481f-9576-68376397403b", "text": "Igaz", "isCorrect": true}, {"id": "3183b17f-9b4a-4eef-a514-f6fad709845c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "08d34eb0-bc50-4c55-84da-4fb1131aaa05", "text": "Mi a 20 legkisebb pozitív osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "507f4151-4f7b-4ceb-90e8-0a846282dac5", "text": "Mi a 20 legnagyobb osztója önmagán kívül?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('83920406-8ec1-49c3-8410-5c37b6283274', '21feff02-016d-46e2-bb9d-c27495133b1b', '14. óra: Számolás maradékokkal', 'Az osztási maradék fogalma, paritás vizsgálata, összeg maradéka.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "d1c59a8f-03de-4ae6-b915-fe8cec167ea8", "text": "Mennyi a maradék, ha 23-at elosztjuk 5-tel? (23 = 4*5 + 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "4ddf6381-f163-4039-ac5b-49f8c42903e9", "text": "Egy számot 4-gyel elosztva a lehetséges maradékok: 0, 1, 2, 3.", "type": "true-false", "options": [{"id": "e572fc42-9660-4a87-9741-81644c14239a", "text": "Igaz", "isCorrect": true}, {"id": "c50941e0-6829-477e-addb-df5b4312aa31", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2cd6e6b4-4469-4bd9-9325-7df361e5695c", "text": "Milyen maradékot ad 2-vel osztva minden páratlan szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "58a9f2ee-3694-401d-a101-9c423aa6cab0", "text": "Két páratlan szám összege mindig páros szám.", "type": "true-false", "options": [{"id": "226c986b-40f0-495e-8cb3-a41a99cfd7c3", "text": "Igaz (páratlan + páratlan = páros)", "isCorrect": true}, {"id": "02771b1d-c51d-442d-bf64-493a883a0a96", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "12fbb8b5-155d-4235-897b-bff1af521f01", "text": "Mennyi a maradék 37 : 10 esetén?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "9bfcf094-e047-4760-9bd4-b749212579c8", "text": "Két páros szám szorzata mindig páros szám.", "type": "true-false", "options": [{"id": "28cf7013-1b6f-436b-a638-2cfcf0595168", "text": "Igaz", "isCorrect": true}, {"id": "0d313fa8-7edb-423d-9b22-a68878aa2c43", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "75c7a3c6-4dce-46ea-8a16-f004873e5dbf", "text": "Melyik szám ad 0 maradékot 3-mal osztva?", "type": "multiple-choice", "options": [{"id": "11d31a8c-e89e-4654-9d1c-ea8337dc52e4", "text": "15", "isCorrect": true}, {"id": "73785332-cb7a-4ab5-923b-ac3a626a037a", "text": "16", "isCorrect": false}, {"id": "67b786a2-42ac-4699-ac29-34e2be98e281", "text": "17", "isCorrect": false}, {"id": "25b4883a-98f9-4eb2-aa06-39c867269375", "text": "19", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('1821699e-f977-49d2-9693-64ab96e20031', '21feff02-016d-46e2-bb9d-c27495133b1b', '15. óra: Hány osztója van?', 'Természetes számok csoportosítása osztóik száma alapján, prímek és összetett számok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "b6fe96ee-2a0d-4074-a79d-c182c6a76d67", "text": "Hogyan nevezzük azokat a számokat, amelyeknek pontosan 2 osztójuk van (1 és önmaga)?", "type": "multiple-choice", "options": [{"id": "d363b283-a755-4161-8d1a-eadc3455011b", "text": "Prímszámok (prímek)", "isCorrect": true}, {"id": "00348588-c68f-4c52-8920-dca94d09c109", "text": "Összetett számok", "isCorrect": false}, {"id": "67091fdf-2e18-4696-9cf4-92dd3d26a110", "text": "Páros számok", "isCorrect": false}, {"id": "a9ef659a-10c4-491c-9fb4-5d01c6fbc505", "text": "Negatív számok", "isCorrect": false}], "timeLimit": 15}, {"id": "31affcc9-7b65-4c15-a68d-b4b4a7866e1d", "text": "Az 1 prímszám.", "type": "true-false", "options": [{"id": "d3eb0e91-aff8-4758-a5f8-d291d5e7c7d0", "text": "Igaz", "isCorrect": false}, {"id": "f2c97adb-b08f-482d-b853-5784d334c427", "text": "Hamis (az 1 sem nem prím, sem nem összetett)", "isCorrect": true}], "timeLimit": 15}, {"id": "d98bbeed-3a65-4ea6-a47b-89cce95f3e7d", "text": "Melyik a legkisebb prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "d8ae54e6-f4d8-452a-9eb5-03e83fc9b9f4", "text": "Melyik az egyetlen páros prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "9401d62c-8b0e-46aa-a6e4-733296a456dc", "text": "Azokat a számokat, amelyeknek 2-nél több osztójuk van, összetett számoknak nevezzük.", "type": "true-false", "options": [{"id": "d0c5106e-ab0e-4c67-9e12-b02ec49caa1e", "text": "Igaz", "isCorrect": true}, {"id": "527da78e-57f0-4558-940f-d17e238f32b3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c0a66a6-cbe0-46b9-b742-85b5bda60978", "text": "Hány osztója van a 7-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "8a059bc3-9211-4733-a176-57cdde842d5a", "text": "Melyik prím az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "d0646cf9-368f-4574-aec5-a106d476d73c", "text": "13", "isCorrect": true}, {"id": "fac51322-7505-4049-953a-d9c42d9ed0ad", "text": "9", "isCorrect": false}, {"id": "f412705b-3abe-4e04-86e5-347cc707eea9", "text": "15", "isCorrect": false}, {"id": "6bddcd2a-ea80-45e4-92f6-787871bc4aba", "text": "21", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('8bffd68e-a1c2-454e-a499-781f72680569', '21feff02-016d-46e2-bb9d-c27495133b1b', '16. óra: Feladatok az osztók számának meghatározására, számolás maradékokkal', 'Szöveges feladatok az osztókról és maradékokról.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "9f498c11-46fc-415f-b570-447f03c71d51", "text": "Hány osztója van a 9-nek? (1, 3, 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "4ab6c193-687c-4ba9-bb49-aba1025dcbde", "text": "A négyzetszámoknak páratlan számú osztójuk van.", "type": "true-false", "options": [{"id": "787e0980-1e33-427c-9e2c-204d6a479753", "text": "Igaz (pl. 9-nek 3 osztója van: 1, 3, 9)", "isCorrect": true}, {"id": "7c38e999-8288-4006-8270-254ffbd5904b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "db744422-fe4c-4b74-bc54-5660ac41c773", "text": "Ha 25 alma van és 4 gyerek között egyenlően elosztjuk, hány alma marad a kosárban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "cc288a55-862d-46c6-860d-d0cf85b1f65d", "text": "Hány prímszám van 10 és 20 között? (11, 13, 17, 19)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "fa35f629-fe41-4c84-9128-3e94fcbcb4fa", "text": "Melyik szám összetett szám az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "ffda7c60-56c9-466a-9a83-77989945c4e1", "text": "27 (osztói: 1,3,9,27)", "isCorrect": true}, {"id": "1e85c2d1-8174-43cf-84a9-4a69c9073ce0", "text": "23", "isCorrect": false}, {"id": "b56d3fcc-5db3-4b65-91b5-bbfe73c39a8c", "text": "29", "isCorrect": false}, {"id": "a035c7d1-d46c-49d7-b042-bf6581b160e7", "text": "31", "isCorrect": false}], "timeLimit": 15}, {"id": "faee6484-99c8-4f4a-808c-af506e542832", "text": "Minden páratlan szám prímszám.", "type": "true-false", "options": [{"id": "b68a678b-cb46-44be-bc9b-7960b1ba9769", "text": "Igaz", "isCorrect": false}, {"id": "91ab7162-07bd-4edb-b6f8-d033bc56598b", "text": "Hamis (pl. 9, 15, 2